```tsx
// CheckoutPage.tsx
import React, { useMemo, useState } from "react";
import "./CheckoutPage.css";
import { CartItem, CheckoutPageProps, DeliveryAddress } from "./types";

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  addressLine1: "",
  addressLine2: "",
  city: "",
  postalCode: "",
  country: "",
  phone: "",
};

type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;

const REQUIRED_FIELDS: (keyof DeliveryAddress)[] = [
  "fullName",
  "addressLine1",
  "city",
  "postalCode",
  "country",
  "phone",
];

function formatPrice(amount: number, currency: string): string {
  try {
    return new Intl.NumberFormat(undefined, {
      style: "currency",
      currency,
    }).format(amount);
  } catch {
    return `${currency} ${amount.toFixed(2)}`;
  }
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  REQUIRED_FIELDS.forEach((field) => {
    if (!address[field] || !address[field]!.trim()) {
      errors[field] = "This field is required.";
    }
  });

  if (address.phone && !/^[+\d][\d\s()-]{5,}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number.";
  }

  if (
    address.postalCode &&
    !/^[A-Za-z0-9][A-Za-z0-9\s-]{1,9}$/.test(address.postalCode.trim())
  ) {
    errors.postalCode = "Enter a valid postal code.";
  }

  return errors;
}

const CartList: React.FC<{ items: CartItem[]; currency: string }> = ({
  items,
  currency,
}) => {
  if (items.length === 0) {
    return <p className="checkout-empty">Your cart is empty.</p>;
  }

  return (
    <ul className="cart-list">
      {items.map((item) => (
        <li key={item.id} className="cart-list__item">
          {item.imageUrl ? (
            <img
              className="cart-list__image"
              src={item.imageUrl}
              alt={item.name}
            />
          ) : (
            <div className="cart-list__image cart-list__image--placeholder" />
          )}
          <div className="cart-list__details">
            <span className="cart-list__name">{item.name}</span>
            <span className="cart-list__qty">Qty: {item.quantity}</span>
          </div>
          <span className="cart-list__price">
            {formatPrice(item.price * item.quantity, currency)}
          </span>
        </li>
      ))}
    </ul>
  );
};

interface AddressFormProps {
  address: DeliveryAddress;
  errors: AddressErrors;
  onChange: (field: keyof DeliveryAddress, value: string) => void;
}

const AddressForm: React.FC<AddressFormProps> = ({
  address,
  errors,
  onChange,
}) => {
  const renderField = (
    field: keyof DeliveryAddress,
    label: string,
    options?: { placeholder?: string; optional?: boolean }
  ) => (
    <div className="form-field">
      <label className="form-field__label" htmlFor={field}>
        {label}
        {!options?.optional && <span className="form-field__required">*</span>}
      </label>
      <input
        id={field}
        name={field}
        type="text"
        className={`form-field__input ${errors[field] ? "form-field__input--error" : ""}`}
        placeholder={options?.placeholder}
        value={address[field] ?? ""}
        onChange={(e) => onChange(field, e.target.value)}
        autoComplete="on"
      />
      {errors[field] && (
        <span className="form-field__error">{errors[field]}</span>
      )}
    </div>
  );

  return (
    <fieldset className="address-form">
      <legend className="address-form__legend">Delivery address</legend>

      {renderField("fullName", "Full name")}
      {renderField("addressLine1", "Address line 1")}
      {renderField("addressLine2", "Address line 2", { optional: true })}

      <div className="address-form__row">
        {renderField("city", "City")}
        {renderField("postalCode", "Postal code")}
      </div>

      <div className="address-form__row">
        {renderField("country", "Country")}
        {renderField("phone", "Phone number", { placeholder: "+1 555 123 4567" })}
      </div>
    </fieldset>
  );
};

const CheckoutPage: React.FC<CheckoutPageProps> = ({
  cartItems,
  onBackToCart,
  onPay,
  currency = "USD",
}) => {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [isPaying, setIsPaying] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [cartItems]
  );
  const shipping = cartItems.length > 0 ? 5 : 0;
  const total = subtotal + shipping;

  const handleFieldChange = (field: keyof DeliveryAddress, value: string) => {
    setAddress((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  };

  const handlePay = async () => {
    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setPayError(null);

    if (Object.keys(validationErrors).length > 0) {
      return;
    }
    if (cartItems.length === 0) {
      setPayError("Your cart is empty.");
      return;
    }

    setIsPaying(true);
    try {
      await onPay(address);
    } catch (err) {
      setPayError(
        err instanceof Error ? err.message : "Payment failed. Please try again."
      );
    } finally {
      setIsPaying(false);
    }
  };

  return (
    <div className="checkout-page">
      <h1 className="checkout-page__title">Checkout</h1>

      <div className="checkout-page__layout">
        <section className="checkout-section">
          <h2 className="checkout-section__title">Your items</h2>
          <CartList items={cartItems} currency={currency} />
        </section>

        <section className="checkout-section">
          <AddressForm
            address={address}
            errors={errors}
            onChange={handleFieldChange}
          />
        </section>

        <section className="checkout-section checkout-summary">
          <h2 className="checkout-section__title">Order summary</h2>
          <div className="checkout-summary__row">
            <span>Subtotal</span>
            <span>{formatPrice(subtotal, currency)}</span>
          </div>
          <div className="checkout-summary__row">
            <span>Shipping</span>
            <span>{formatPrice(shipping, currency)}</span>
          </div>
          <div className="checkout-summary__row checkout-summary__row--total">
            <span>Total</span>
            <span>{formatPrice(total, currency)}</span>
          </div>

          {payError && <p className="checkout-summary__error">{payError}</p>}

          <div className="checkout-actions">
            <button
              type="button"
              className="btn btn--secondary"
              onClick={onBackToCart}
              disabled={isPaying}
            >
              Back to cart
            </button>
            <button
              type="button"
              className="btn btn--primary"
              onClick={handlePay}
              disabled={isPaying || cartItems.length === 0}
            >
              {isPaying ? "Processing…" : `Pay ${formatPrice(total, currency)}`}
            </button>
          </div>
        </section>
      </div>
    </div>
  );
};

export default CheckoutPage;
```

